# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ASLİ MED (MEDD-İ TABİÎ) VE MED SEBEPLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">MED HARFLERİ (حُرُوفُ الْمَدِّ) — 3 HARF</text>\n  <text x="42" y="98" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. Elif (ا): Kendisi harekesiz, öncesi ÜSTÜN (ـَ ا)</text>\n  <text x="52" y="116" font-size="11" fill="#334155">Örnek: قَالَ (Kâle) - كَانَ (Kâne)</text>\n  <text x="42" y="142" font-size="11.5" font-weight="bold" fill="#1e3a8a">2. Vâv (و): Kendisi sakin, öncesi ÖTRE (ـُ وْ)</text>\n  <text x="52" y="160" font-size="11" fill="#334155">Örnek: يَقُولُ (Yekûlu) - نُورٌ (Nûrun)</text>\n  <text x="42" y="186" font-size="11.5" font-weight="bold" fill="#1e3a8a">3. Yâ (ي): Kendisi sakin, öncesi ESRE (ـِ يْ)</text>\n  <text x="52" y="204" font-size="11" fill="#334155">Örnek: قِيلَ (Kîle) - دِينِ (Dîni)</text>\n  <text x="182" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Ölçüsü: 1 Elif miktarı uzatılır (Sebeb-i med yoksa).</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">SEBEB-İ MED (FER\'Î MED SEBEPLERİ)</text>\n  <text x="377" y="96" font-size="11" fill="#334155">Med harfinden sonra gelerek uzatmayı 1 eliften</text>\n  <text x="377" y="112" font-size="11" fill="#334155">(2, 3 veya 4 elife) çıkaran iki temel sebep vardır:</text>\n  <text x="377" y="138" font-size="12" font-weight="bold" fill="#14532d">1. HEMZE (ء / أَ إِ أُ):</text>\n  <text x="387" y="156" font-size="10.5" fill="#334155">→ Aynı kelimede ise: Medd-i Muttasıl</text>\n  <text x="387" y="172" font-size="10.5" fill="#334155">→ Ayrı kelimede ise: Medd-i Munfasıl</text>\n  <text x="377" y="198" font-size="12" font-weight="bold" fill="#14532d">2. SÜKÛN (Cezim veya Şedde):</text>\n  <text x="387" y="216" font-size="10.5" fill="#334155">→ Lâzım Sükûn (Medd-i Lâzım) / Ârız Sükûn (Medd-i Ârız)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HEMZE SEBEBİYLE OLUŞAN FER\'Î MEDLER: MUTTASIL VE MUNFASIL</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">MEDD-İ MUTTASIL (BİTİŞİK MED)</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#713f12">• Tanım: Med harfinden sonra gelen hemzenin</text>\n  <text x="52" y="114" font-size="11" font-weight="bold" fill="#dc2626">AYNI KELİME İÇİNDE bulunmasıdır.</text>\n  <text x="42" y="140" font-size="11.5" font-weight="bold" fill="#713f12">• Örnekler: جَآءَ (Câe) · سُوٓءَ (Sûe) · اَلْمَلٰٓئِكَةُ</text>\n  <text x="42" y="166" font-size="11.5" font-weight="bold" fill="#713f12">• Uzatma Miktarı: Asım kıraatinde 4 elif</text>\n  <text x="52" y="184" font-size="10.5" fill="#334155">(hızlı okuyuşta en az 2 elif) uzatılır.</text>\n  <text x="42" y="212" font-size="11.5" font-weight="bold" fill="#854d0e">• Hükmü: VACİPTİR (Kıraat imamları ittifaklıdır).</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">MEDD-İ MUNFASIL (AYRIK MED)</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#581c87">• Tanım: Med harfinin kelimenin sonunda, uzun</text>\n  <text x="387" y="114" font-size="11" font-weight="bold" fill="#9333ea">hemzenin İKİNCİ KELİMENİN BAŞINDA olmasıdır.</text>\n  <text x="377" y="140" font-size="11.5" font-weight="bold" fill="#581c87">• Örnekler: يَآ أَيُّهَا · إِنَّآ أَعْطَيْنَاكَ · قُوٓا أَنْفُسَكُمْ</text>\n  <text x="377" y="166" font-size="11.5" font-weight="bold" fill="#581c87">• Uzatma Miktarı: 1 ile 4 elif arası uzatılır.</text>\n  <text x="387" y="184" font-size="10.5" fill="#334155">(Zamir meddi / Medd-i Sıla da munfasıla dâhildir.)</text>\n  <text x="377" y="212" font-size="11.5" font-weight="bold" fill="#6b21a8">• Hükmü: CAİZDİR (Kasr ile de okunabilir).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SÜKÛN SEBEBİYLE OLUŞAN FER\'Î MEDLER: LÂZIM, ÂRIZ VE LÎN</text>\n  <rect x="25" y="45" width="205" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">MEDD-İ LÂZIM</text>\n  <text x="38" y="94" font-size="11" font-weight="bold" fill="#7f1d1d">• Sebep: Lâzım (Kalıcı) Sükûn</text>\n  <text x="45" y="110" font-size="10" fill="#334155">(Durulsa da geçilse de sabit</text>\n  <text x="45" y="124" font-size="10" fill="#334155">olan cezim veya şedde).</text>\n  <text x="38" y="148" font-size="11" font-weight="bold" fill="#7f1d1d">• Örnek: وَلَا الضَّآلِّينَ · الٓمٓ</text>\n  <text x="38" y="172" font-size="11" font-weight="bold" fill="#7f1d1d">• Miktarı: 4 Elif (En uzun)</text>\n  <text x="38" y="196" font-size="11" font-weight="bold" fill="#dc2626">• Hükmü: VACİP (Kesin)</text>\n  <rect x="247" y="45" width="205" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">MEDD-İ ÂRIZ</text>\n  <text x="260" y="94" font-size="11" font-weight="bold" fill="#7c2d12">• Sebep: Ârız (Geçici) Sükûn</text>\n  <text x="267" y="110" font-size="10" fill="#334155">(Vakıf yapıldığında son harfin</text>\n  <text x="267" y="124" font-size="10" fill="#334155">harekesinin cezimlenmesi).</text>\n  <text x="260" y="148" font-size="11" font-weight="bold" fill="#7c2d12">• Örnek: اَلْعَالَمِينَ ← اَلْعَالَمِينْ</text>\n  <text x="260" y="172" font-size="11" font-weight="bold" fill="#7c2d12">• Miktarı: Tul(4), Tevassut(2-3),</text>\n  <text x="267" y="187" font-size="10" fill="#334155">Kasr(1 elif). Geçilirse Tabiî olur!</text>\n  <text x="260" y="210" font-size="11" font-weight="bold" fill="#ea580c">• Hükmü: CAİZDİR</text>\n  <rect x="470" y="45" width="205" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">MEDD-İ LÎN</text>\n  <text x="483" y="94" font-size="11" font-weight="bold" fill="#14532d">• Sebep: Harf-i Lîn + Sükûn</text>\n  <text x="490" y="110" font-size="10" fill="#334155">Cezimli وْ veya يْ \'den önce</text>\n  <text x="490" y="124" font-size="10" fill="#334155">ÜSTÜN (ـَ) gelip durulması.</text>\n  <text x="483" y="148" font-size="11" font-weight="bold" fill="#14532d">• Örnek: قُرَيْشٍ ← قُرَيْشْ</text>\n  <text x="490" y="164" font-size="10.5" fill="#14532d">خَوْفٍ ← خَوْفْ · اَلصَّيْفْ</text>\n  <text x="483" y="188" font-size="11" font-weight="bold" fill="#14532d">• Hükmü: CAİZDİR</text>\n  <text x="490" y="206" font-size="10" fill="#334155">(Durulmazsa uzatma yapılmaz)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
